/// 줄인 글자 → 원래 글 (생성기의 TOKENS 를 거꾸로)
pub fn expand(packed: &str) -> String {
    let mut s = packed.to_string();
    s = s.replace('Û', "<pathLst>");
    s = s.replace('Ú', "</pathLst>");
    s = s.replace('Ù', "<avLst>");
    s = s.replace('Ø', "</avLst>");
    s = s.replace('Ö', "<gdLst>");
    s = s.replace('Õ', "</gdLst>");
    s = s.replace('Ô', "</path>");
    s = s.replace('Ó', "<path");
    s = s.replace('Ò', "<close/>");
    s = s.replace('Ñ', "</quadBezTo>");
    s = s.replace('Ð', "<quadBezTo>");
    s = s.replace('Ï', "</cubicBezTo>");
    s = s.replace('Î', "<cubicBezTo>");
    s = s.replace('Í', "\" swAng=\"");
    s = s.replace('Ì', "\" stAng=\"");
    s = s.replace('Ë', "\" hR=\"");
    s = s.replace('Ê', "<arcTo wR=\"");
    s = s.replace('É', "</lnTo>");
    s = s.replace('È', "<lnTo>");
    s = s.replace('Ç', "</moveTo>");
    s = s.replace('Æ', "<moveTo>");
    s = s.replace('Å', "\" y=\"");
    s = s.replace('Ä', "<pt x=\"");
    s = s.replace('Ã', "\"/>");
    s = s.replace('Â', "\" fmla=\"");
    s = s.replace('Á', "<gd name=\"");
    s
}

